document.addEventListener("DOMContentLoaded", () => {
    const e = document.querySelector("#charity-card-select"), t = Array.from(document.querySelectorAll(".charity-card"));
    e && 0 !== t.length && (t.forEach((t, n) => {
        const c = t.querySelector(".charity-card__name"), o = c?.textContent.trim();
        if (!o) return;
        const r = t.id || `charity-card-${n + 1}`;
        t.id = r;
        const a = document.createElement("option");
        a.value = r, a.textContent = o, e.appendChild(a)
    }), e.addEventListener("change", () => {
        const t = document.getElementById(e.value);
        t && (t.scrollIntoView({behavior: "smooth", block: "start"}), e.value = "")
    }))
});